/* Force visible black table borders (default is a faint #d1d8dd) */
.print-format table.table-bordered,
.print-format table.table-bordered > thead > tr > th,
.print-format table.table-bordered > thead > tr > td,
.print-format table.table-bordered > tbody > tr > th,
.print-format table.table-bordered > tbody > tr > td {
	border: 1px solid #000 !important;
}

/* Browser print fixes for BSP Sales/Purchase Invoice (PDF uses wkhtmltopdf). */
@media print {
	@page {
		size: A4 portrait;
		margin: 10mm;
	}

	html,
	body {
		height: auto !important;
		overflow: visible !important;
	}

	.print-format-gutter {
		padding: 0 !important;
		background: #fff !important;
	}

	.print-format {
		padding: 0 !important;
		margin: 0 !important;
		min-height: 0 !important;
		max-width: none !important;
		width: 100% !important;
		border-radius: 0 !important;
		box-shadow: none !important;
	}

	#header-html,
	#footer-html,
	footer,
	.bsp-print-footer {
		display: block !important;
	}

	.visible-pdf.bsp-print-footer,
	#footer-html.bsp-print-footer,
	#footer-html {
		display: block !important;
	}

	.page-number,
	.visible-pdf.page-number {
		display: none !important;
	}

	#footer-html,
	.bsp-print-footer {
		page-break-inside: avoid;
		margin-top: 12px !important;
	}

	.letter-head-footer {
		page-break-inside: avoid;
		margin-top: 16px !important;
	}

	.bsp-print-spacer {
		padding-bottom: 12px !important;
		min-height: 0 !important;
	}

	table.table-bordered {
		page-break-inside: auto;
	}

	table.table-bordered tr {
		page-break-inside: avoid;
	}
}

