	.print-format { padding: 0 !important; margin: 0 !important; min-height: 0 !important; max-width: none !important; width: 100% !important; border-radius: 0 !important; box-shadow: none !important; }
	#header-html, #footer-html, footer, .bsp-print-footer { display: block !important; }
}

