/* BSP Delivery Note print CSS (real PDF generation via wkhtmltopdf) */
@media print {
	.print-format-gutter { padding: 0 !important; background: #fff !important; }
	.print-format { padding: 0 !important; margin: 0 !important; min-height: 0 !important; max-width: none !important; width: 100% !important; border-radius: 0 !important; box-shadow: none !important; }
	#header-html, #footer-html, footer, .bsp-print-footer { display: block !important; }
}

/* Force visible black table borders (default is a faint #d1d8dd).
   border-collapse:collapse is required alongside this -- without it,
   adjacent cell borders are drawn as separate, independently-positioned
   lines (browser default is border-collapse:separate), which is why the
   table's outer/top border can render thin, doubled, or seemingly missing
   depending on the rendering engine. */
.print-format table.table-bordered {
	border-collapse: collapse !important;
}
.print-format table.table-bordered,
.print-format table.table-bordered > thead > tr > th,
.print-format table.table-bordered > thead > tr > td,
.print-format table.table-bordered > tbody > tr > th,
.print-format table.table-bordered > tbody > tr > td {
	border: 1px solid #000 !important;
}

/* Unlike Material Transfer/Requisition (item codes, short structured
   fields), this format's Description is a long auto-generated sentence and
   several fields contain Bengali account/user names -- both are exactly
   the kind of content that can fail to find a break point and overflow
   past the page edge instead of wrapping, in engines with weaker complex-
   script line-breaking. Force wrapping explicitly so long/unbroken content
   can never push the table past the printable width. */
.print-format table.table-bordered > tbody > tr > td,
.print-format table.table-bordered > thead > tr > th {
	word-wrap: break-word;
	overflow-wrap: break-word;
	word-break: break-word;
}

/* BSP Fundtransfer print CSS (real PDF generation via wkhtmltopdf).
   Deliberately NOT overriding @page margin here: this print format sets
   .print-format padding to 0 and relies entirely on wkhtmltopdf's own
   command-line margin options for spacing (2mm/15mm/45mm/15mm) instead of
   Frappe's default `.print-format { padding: 0.75in }` (standard.css).
   @page{margin:0} would suppress the browser's print date/title/URL
   chrome, but since the SAME HTML/CSS feeds both the wkhtmltopdf PDF path
   and the browser print path, any CSS padding added to compensate for the
   removed page margin double-counts against wkhtmltopdf's own margins --
   confirmed twice (top/bottom padding pushed content to a 2nd page;
   left/right padding narrowed the content and broke word-wrapping). Left
   out entirely rather than risk a third regression only visible in the
   PDF path. */
@media print {
	.print-format-gutter { padding: 0 !important; background: #fff !important; }
	.print-format { padding: 0 !important; margin: 0 !important; min-height: 0 !important; max-width: none !important; width: 100% !important; border-radius: 0 !important; box-shadow: none !important; }
	#header-html, #footer-html, footer, .bsp-print-footer { display: block !important; }
}
